// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint8 k, uint96 amount) public {
        uint256 count = uint256(bound(uint256(k), 1, 64));
        uint256 amt = uint256(bound(uint256(amount), 0, type(uint96).max));
        address depositor = address(0xA11CE);
        vm.deal(depositor, amt * count);
        for (uint256 i = 0; i < count; i++) {
            vm.prank(depositor);
            (bool ok, ) = address(c).call{value: amt}("");
            assertTrue(ok, "deposit must succeed");
        }
        // General rule: depositsCount equals the number of accepted deposits.
        assertTrue(c.depositsCount() == count, "one deposit must increase counter by exactly one");
    }
}
